package com.ruoyi.paismart.application.intelligence;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.util.Set;

class ControlledHttpTest {
    @Test void refusesRedirectTargetsSecretsAndUnexpectedSchemes(){var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));when(config.enabled("allow-http")).thenReturn(true);try(ControlledHttp http=new ControlledHttp(config)){assertThrows(IllegalArgumentException.class,()->http.validated("https://unapproved.example"));assertThrows(IllegalArgumentException.class,()->http.validated("ftp://approved.example"));assertThrows(IllegalArgumentException.class,()->http.validated("https://secret@approved.example"));assertThrows(IllegalArgumentException.class,()->http.validated("https://approved.example?key=secret"));assertEquals("approved.example",http.validated("https://approved.example/v1").getHost());}}
    @SuppressWarnings("unchecked") @Test void stopBeforeResponseHeadersCancelsTheActualPendingHttpFuture(){
        var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));var client=mock(java.net.http.HttpClient.class);var response=new java.util.concurrent.CompletableFuture<java.net.http.HttpResponse<java.io.InputStream>>();when(client.sendAsync(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class))).thenReturn(response);
        try(var http=new ControlledHttp(config)){org.springframework.test.util.ReflectionTestUtils.setField(http,"client",client);var checks=new java.util.concurrent.atomic.AtomicInteger();assertTimeoutPreemptively(java.time.Duration.ofSeconds(4),()->assertThrows(java.util.concurrent.CancellationException.class,()->http.sse("https://approved.example/chat/completions","test",java.util.Map.of(),data->fail("无响应时不可输出"),()->checks.incrementAndGet()>2)));assertTrue(response.isCancelled());verify(client,times(1)).sendAsync(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class));verify(client,never()).send(any(),any());}
        catch(InterruptedException|java.io.IOException impossible){throw new AssertionError(impossible);}
    }
    @SuppressWarnings("unchecked") @Test void revokedLeaseWhileWaitingForHeadersCancelsTheRequestAndKeepsItsGuardError(){
        var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));var client=mock(java.net.http.HttpClient.class);var response=new java.util.concurrent.CompletableFuture<java.net.http.HttpResponse<java.io.InputStream>>();when(client.sendAsync(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class))).thenReturn(response);
        try(var http=new ControlledHttp(config)){org.springframework.test.util.ReflectionTestUtils.setField(http,"client",client);var checks=new java.util.concurrent.atomic.AtomicInteger();var failure=assertThrows(IllegalStateException.class,()->http.sse("https://approved.example/chat/completions","test",java.util.Map.of(),data->{},()->{if(checks.incrementAndGet()>2)throw new IllegalStateException("lost lease");return false;}));assertEquals("lost lease",failure.getMessage());assertTrue(response.isCancelled());}
    }
    @SuppressWarnings("unchecked") @Test void normalSseReadsRealLinesAndClosesTheAcquiredStreamAfterDone(){
        var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));var client=mock(java.net.http.HttpClient.class);java.net.http.HttpResponse<java.io.InputStream> response=mock(java.net.http.HttpResponse.class);var closed=new java.util.concurrent.atomic.AtomicBoolean();String payload="data: {\"choices\":[{\"delta\":{\"content\":\"甲\"}}]}\n\ndata: {\"choices\":[{\"delta\":{\"tool_calls\":[{\"index\":0,\"function\":{\"arguments\":\"{}\"}}]}}]}\n\ndata: [DONE]\n";
        var input=new java.io.ByteArrayInputStream(payload.getBytes(java.nio.charset.StandardCharsets.UTF_8)){@Override public void close()throws java.io.IOException{closed.set(true);super.close();}};when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn(input);when(client.sendAsync(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class))).thenReturn(java.util.concurrent.CompletableFuture.completedFuture(response));
        try(var http=new ControlledHttp(config)){org.springframework.test.util.ReflectionTestUtils.setField(http,"client",client);java.util.List<java.util.Map<String,Object>> chunks=new java.util.ArrayList<>();http.sse("https://approved.example/chat/completions","test",java.util.Map.of(),chunks::add,()->false);assertEquals(2,chunks.size());assertTrue(chunks.get(0).toString().contains("甲"));assertTrue(chunks.get(1).toString().contains("tool_calls"));assertTrue(closed.get());}
    }
    @SuppressWarnings("unchecked") @Test void delayedJsonHeadersLeaveOnlyTheRemainingBodyBudget()throws Exception{
        var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));var client=mock(java.net.http.HttpClient.class);java.net.http.HttpResponse<java.io.InputStream> response=mock(java.net.http.HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn(new java.io.ByteArrayInputStream("{\"ok\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8)));when(client.send(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class))).thenAnswer(i->{Thread.sleep(120);return response;});
        var scheduler=mock(java.util.concurrent.ScheduledExecutorService.class);var timer=mock(java.util.concurrent.ScheduledFuture.class);doReturn(timer).when(scheduler).schedule(any(Runnable.class),anyLong(),eq(java.util.concurrent.TimeUnit.NANOSECONDS));
        try(var http=new ControlledHttp(config)){var original=(java.util.concurrent.ScheduledExecutorService)org.springframework.test.util.ReflectionTestUtils.getField(http,"watchdog");try{org.springframework.test.util.ReflectionTestUtils.setField(http,"client",client);org.springframework.test.util.ReflectionTestUtils.setField(http,"watchdog",scheduler);assertEquals(true,http.json("POST","https://approved.example/test",null,java.util.Map.of(),1).get("ok"));var delay=org.mockito.ArgumentCaptor.forClass(Long.class);verify(scheduler).schedule(any(Runnable.class),delay.capture(),eq(java.util.concurrent.TimeUnit.NANOSECONDS));assertTrue(delay.getValue()>0);assertTrue(delay.getValue()<java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(950),"等响应头所花时间必须从同一秒预算扣除");verify(timer).cancel(false);}finally{original.shutdownNow();}}
    }
    @SuppressWarnings("unchecked") @Test void jsonBodyArrivingAfterDeadlineIsClosedWithoutReadingOrReportingSuccess()throws Exception{
        var config=mock(IntelligenceSettings.class);when(config.hosts()).thenReturn(Set.of("approved.example"));var client=mock(java.net.http.HttpClient.class);java.net.http.HttpResponse<java.io.InputStream> response=mock(java.net.http.HttpResponse.class);var closed=new java.util.concurrent.atomic.AtomicBoolean();var reads=new java.util.concurrent.atomic.AtomicInteger();var input=new java.io.ByteArrayInputStream("{\"ok\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8)){@Override public byte[] readNBytes(int len){reads.incrementAndGet();return new byte[0];}@Override public void close(){closed.set(true);}};when(response.body()).thenReturn(input);when(client.send(any(java.net.http.HttpRequest.class),any(java.net.http.HttpResponse.BodyHandler.class))).thenAnswer(i->{Thread.sleep(1100);return response;});
        try(var http=new ControlledHttp(config)){org.springframework.test.util.ReflectionTestUtils.setField(http,"client",client);var failure=assertThrows(IllegalStateException.class,()->http.json("POST","https://approved.example/test",null,java.util.Map.of(),1));assertTrue(failure.getMessage().contains("时间预算"));assertTrue(closed.get());assertEquals(0,reads.get());}
    }
}
